import React, { useState, useMemo, useCallback } from "react";
import "../styles/SkinAnalyzer.css";

export default function SkinAnalyzer() {
  const [photo, setPhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [analysis, setAnalysis] = useState(null);
  const [recommendations, setRecommendations] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadingRec, setLoadingRec] = useState(false);
  const [selectedProcedure, setSelectedProcedure] = useState(null);
  const [treatmentPlan, setTreatmentPlan] = useState(null);
  const [progress, setProgress] = useState([]);

  // 🔹 Основные обработчики событий (по требованиям лабы)

  // 1. Обработчик анализа кожи
  const onSkinAnalyze = useCallback(async (photoFile) => {
    if (!photoFile) {
      alert("Загрузите фото!");
      return null;
    }

    setLoading(true);
    const formData = new FormData();
    formData.append("photo", photoFile);

    try {
      const res = await fetch("http://localhost:4000/api/skin/analyze", {
        method: "POST",
        credentials: "include",
        body: formData,
      });

      if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);

      const data = await res.json();
      setAnalysis(data);

      // Возвращаем данные анализа для цепочек Promise
      return data;
    } catch (err) {
      console.error("Ошибка анализа кожи:", err);
      alert("Ошибка анализа кожи: " + err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  // 2. Обработчик бронирования записи (Promise цепочка)
  const onAppointmentBook = useCallback(async (appointmentData) => {
    return new Promise(async (resolve, reject) => {
      try {
        // Цепочка промисов: консультация → выбор процедуры → бронирование → подготовка
        console.log("🚀 Начало цепочки записи...");

        // Шаг 1: Консультация (если есть анализ кожи)
        if (analysis) {
          console.log("✅ Консультация на основе анализа кожи");
          await new Promise(resolve => setTimeout(resolve, 500)); // Имитация задержки
        }

        // Шаг 2: Выбор процедуры
        console.log("🔍 Выбор процедуры...");
        const procedure = await selectProcedure(appointmentData.procedureId);
        setSelectedProcedure(procedure);

        // Шаг 3: Бронирование
        console.log("📅 Бронирование времени...");
        const booking = await bookAppointment({
          clientId: appointmentData.clientId,
          procedureId: procedure._id,
          startUtc: appointmentData.startUtc,
        });

        // Шаг 4: Подготовка к визиту
        console.log("🎯 Подготовка рекомендаций...");
        const preparation = await prepareForVisit(booking);

        console.log("✅ Запись успешно завершена!");
        resolve({ booking, preparation });

      } catch (error) {
        console.error("❌ Ошибка в цепочке записи:", error);
        reject(error);
      }
    });
  }, [analysis]);

  // 3. Обработчик планирования курса процедур
  const onTreatmentPlan = useCallback((analysisData) => {
    if (!analysisData) return null;

    // Создаем план лечения на основе анализа
    const plan = createTreatmentPlan(analysisData);
    setTreatmentPlan(plan);

    // Используем setTimeout для напоминаний о следующем визите
    if (plan.nextVisit) {
      const reminderTime = new Date(plan.nextVisit).getTime() - Date.now() - 86400000; // За день до
      if (reminderTime > 0) {
        setTimeout(() => {
          alert(`Напоминание: У вас запланирован визит завтра в ${new Date(plan.nextVisit).toLocaleTimeString()}`);
        }, reminderTime);
      }
    }

    return plan;
  }, []);

  // 4. Обработчик рекомендации продуктов (XMLHttpRequest)
  const onProductRecommend = useCallback((skinType) => {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open("GET", `http://localhost:4000/api/products?skinType=${skinType}`, true);
      xhr.withCredentials = true;

      xhr.onload = function() {
        if (xhr.status === 200) {
          const products = JSON.parse(xhr.responseText);
          resolve(products);
        } else {
          reject(new Error(`Ошибка ${xhr.status}: ${xhr.statusText}`));
        }
      };

      xhr.onerror = function() {
        reject(new Error("Ошибка сети"));
      };

      xhr.send();
    });
  }, []);

  // 5. Обработчик отслеживания прогресса
  const onProgressTrack = useCallback((photos) => {
    // Используем XMLHttpRequest для загрузки фото "до/после"
    const uploadPromises = photos.map((photo, index) => {
      return new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        const formData = new FormData();
        formData.append("photo", photo);
        formData.append("type", index === 0 ? "before" : "after");
        formData.append("timestamp", new Date().toISOString());

        xhr.open("POST", "http://localhost:4000/api/progress/upload", true);
        xhr.withCredentials = true;

        xhr.onload = function() {
          if (xhr.status === 200) {
            const result = JSON.parse(xhr.responseText);
            setProgress(prev => [...prev, result]);
            resolve(result);
          } else {
            reject(new Error(`Ошибка загрузки фото: ${xhr.status}`));
          }
        };

        xhr.onerror = function() {
          reject(new Error("Ошибка сети при загрузке фото"));
        };

        xhr.send(formData);
      });
    });

    return Promise.all(uploadPromises);
  }, []);

  // 🔹 Вспомогательные функции для цепочки промисов

  const selectProcedure = async (procedureId) => {
    const res = await fetch(`http://localhost:4000/api/procedures/${procedureId}`, {
      credentials: "include",
    });
    if (!res.ok) throw new Error("Ошибка выбора процедуры");
    return await res.json();
  };

  const bookAppointment = async (bookingData) => {
    const res = await fetch("http://localhost:4000/api/appointments", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify(bookingData),
    });
    if (!res.ok) throw new Error("Ошибка бронирования");
    return await res.json();
  };

  const prepareForVisit = async (booking) => {
    // Генерация рекомендаций для подготовки к процедуре
    const res = await fetch("http://localhost:4000/api/recommendations/prepare", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ booking, analysis }),
    });
    if (!res.ok) throw new Error("Ошибка подготовки");
    return await res.json();
  };

  const createTreatmentPlan = (analysisData) => {
    const issues = analysisData.analysis?.formatted?.slice(0, 3) || [];
    const plan = {
      title: `Курс лечения (${issues.length} проблемы)`,
      issues,
      procedures: [],
      durationWeeks: Math.ceil(issues.length * 2),
      nextVisit: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      createdAt: new Date().toISOString(),
    };
    return plan;
  };

  // 🔹 Оригинальные функции компонента (модифицированные)

  const handlePhotoChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setPhoto(file);
      const reader = new FileReader();
      reader.onloadend = () => setPhotoPreview(reader.result);
      reader.readAsDataURL(file);
    }
  };

  const analyzeSkin = async () => {
    const result = await onSkinAnalyze(photo);
    if (result) {
      // Автоматически создаем план лечения после анализа
      const plan = onTreatmentPlan(result);
      console.log("Создан план лечения:", plan);
    }
  };

  const getRecommendations = async () => {
    if (!analysis) {
      alert("Сначала сделайте анализ!");
      return;
    }

    setLoadingRec(true);
    try {
      const res = await fetch("http://localhost:4000/api/skin/recommend", {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ skinAnalysis: analysis }),
      });
      const data = await res.json();
      setRecommendations(data.recommendations);

      // Получаем рекомендации продуктов
      if (data.skinType) {
        const products = await onProductRecommend(data.skinType);
        console.log("Рекомендуемые продукты:", products);
      }
    } catch (err) {
      console.error(err);
      alert("Ошибка получения рекомендаций");
    } finally {
      setLoadingRec(false);
    }
  };

  const getPercentageColor = (percent) => {
    const num = parseFloat(percent);
    if (num > 70) return "var(--danger)";
    if (num > 40) return "var(--warning)";
    return "var(--success)";
  };

  // 🔹 useMemo для оптимизации (функциональный компонент)
  const formattedAnalysis = useMemo(() => {
    if (!analysis) return [];
    if (analysis.analysis?.formatted) {
      return analysis.analysis.formatted.map((item) => ({
        ...item,
        displayPercentage: item.percentage || (item.value * 100).toFixed(1),
        color: getPercentageColor(item.percentage || item.value * 100),
      }));
    }
    if (analysis.formatted) {
      return analysis.formatted
        .split("\n")
        .map((line) => {
          const match = line.match(/(.+?) — (\d+\.?\d*)%/);
          if (!match) return null;
          const [, name, percent] = match;
          return { name: name.trim(), displayPercentage: percent, color: getPercentageColor(percent) };
        })
        .filter(Boolean);
    }
    return [];
  }, [analysis]);

  // 🔹 Функции форматирования рекомендаций
  const formatRecommendations = (text) => {
    if (!text) return [];
    const paragraphs = text.split("\n\n").filter((p) => p.trim());
    return paragraphs;
  };

  const formatRecommendationLine = (line, isBold = false) => {
    const cleanLine = line.replace(/^\d+\.\s/, "").replace(/^[-•]\s/, "").trim();
    if (isBold || line.includes("**") || line.match(/^[А-Я].*:/)) {
      return <strong>{cleanLine.replace(/\*\*/g, "")}</strong>;
    }
    const parts = cleanLine.split(/\*\*/);
    return parts.map((part, index) =>
      index % 2 === 1 ? <strong key={index}>{part}</strong> : part
    );
  };

  const getParagraphType = (paragraph) => {
    const firstLine = paragraph.split("\n")[0];
    if (firstLine.includes("Судя по") || firstLine.includes("**")) return "intro";
    if (firstLine.includes("Рекомендации")) return "title";
    if (paragraph.includes("1.") || paragraph.includes("2.") || paragraph.includes("3.")) return "list";
    return "regular";
  };

  // 🔹 Кнопка для тестирования цепочки промисов (можно убрать в финальной версии)
  const testAppointmentChain = async () => {
    if (!analysis) {
      alert("Сначала сделайте анализ кожи!");
      return;
    }

    try {
      const result = await onAppointmentBook({
        clientId: "test-client-id",
        procedureId: "65d8a1b2c8e9f01234567890",
        startUtc: new Date(Date.now() + 86400000).toISOString(),
      });
      alert(`Запись успешна! ID: ${result.booking._id}`);
    } catch (error) {
      alert(`Ошибка записи: ${error.message}`);
    }
  };

  return (
    <div className="skin-analyzer">
      <div className="container">
        <h2 className="title">🧬 Анализ кожи</h2>

        <div className="upload-section">
          <div className="file-input-container">
            <label className="file-input-label">
              <input
                type="file"
                accept="image/*"
                onChange={handlePhotoChange}
                className="file-input"
              />
              <span className="upload-button">📸 Выбрать фото</span>
            </label>
            {photo && <span className="file-name">{photo.name}</span>}
          </div>

          {photoPreview && (
            <div className="photo-preview">
              <img src={photoPreview} alt="Предпросмотр" />
            </div>
          )}

          <button
            onClick={analyzeSkin}
            disabled={loading || !photo}
            className="analyze-button"
          >
            {loading ? (
              <>
                <span className="spinner"></span> Анализируем...
              </>
            ) : (
              "🔍 Анализировать кожу"
            )}
          </button>

          {/* Кнопка тестирования (опционально) */}
          <button
            onClick={testAppointmentChain}
            style={{ marginTop: "10px", background: "var(--primary)" }}
            className="btn"
          >
            🔗 Тест цепочки записи
          </button>
        </div>

        {/* Результаты анализа */}
        {formattedAnalysis.length > 0 && (
          <div className="results-section">
            <h3 className="section-title">
              📊 Результат анализа
              {analysis.summary && (
                <span className="confidence-badge">
                  Достоверность: {analysis.summary.confidence}%
                </span>
              )}
            </h3>

            <div className="analysis-grid">
              {formattedAnalysis.map((item, index) => (
                <div key={index} className="analysis-item">
                  <div className="analysis-header">
                    <span className="item-index">#{index + 1}</span>
                    <span className="item-name">{item.name}</span>
                  </div>
                  <div className="progress-container">
                    <div className="progress-bar">
                      <div
                        className="progress-fill"
                        style={{
                          width: `${item.displayPercentage}%`,
                          backgroundColor: item.color,
                        }}
                      ></div>
                    </div>
                    <span className="percentage" style={{ color: item.color }}>
                      {item.displayPercentage}%
                    </span>
                  </div>
                  <div className="item-level">
                    {item.value > 0.7
                      ? "🔴 Высокая вероятность"
                      : item.value > 0.4
                      ? "🟡 Средняя вероятность"
                      : "🟢 Низкая вероятность"}
                  </div>
                </div>
              ))}
            </div>

            <button
              onClick={getRecommendations}
              disabled={loadingRec}
              className="recommend-button"
            >
              {loadingRec ? (
                <>
                  <span className="spinner"></span> Генерируем рекомендации...
                </>
              ) : (
                "💡 Получить рекомендации по уходу"
              )}
            </button>

            {treatmentPlan && (
              <div style={{ marginTop: "20px", padding: "15px", background: "var(--surface)", borderRadius: "10px" }}>
                <h4>📋 Создан план лечения:</h4>
                <p><strong>Название:</strong> {treatmentPlan.title}</p>
                <p><strong>Длительность:</strong> {treatmentPlan.durationWeeks} недель</p>
                <p><strong>Следующий визит:</strong> {new Date(treatmentPlan.nextVisit).toLocaleDateString()}</p>
              </div>
            )}
          </div>
        )}

        {/* Рекомендации */}
        {recommendations && (
          <div className="recommendations-section">
            <h3 className="section-title">🌟 Рекомендации по уходу</h3>
            <div className="recommendations-card">
              <div className="recommendations-content">
                {formatRecommendations(recommendations).map((paragraph, paraIndex) => {
                  const type = getParagraphType(paragraph);
                  const lines = paragraph.split("\n").filter(line => line.trim());
                  return (
                    <div key={paraIndex} className={`recommendation-paragraph ${type}`}>
                      {lines.map((line, lineIndex) => {
                        const isListItem = line.match(/^\d+\./);
                        const isBold = type === "title" || type === "intro" || line.includes("**");
                        return (
                          <div key={lineIndex} className={`rec-line ${isListItem ? 'list-item' : ''}`}>
                            {isListItem && (
                              <div className="list-marker">
                                <span className="list-number">{line.match(/^\d+/)[0]}</span>
                              </div>
                            )}
                            <div className="rec-text">{formatRecommendationLine(line, isBold)}</div>
                          </div>
                        );
                      })}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
